namespace CampusActivitiesManager.Data
{
    public static class FirebaseConfig
    {
        public const string ProjectId = "campusacmanage";
        public const string ClientEmail = "firebase-adminsdk-fbsvc@campusacmanage.iam.gserviceaccount.com";
        public const string TokenUri = "https://oauth2.googleapis.com/token";
        public const string FirestoreBaseUrl = "https://firestore.googleapis.com/v1/projects/campusacmanage/databases/(default)/documents";

        private const string EncodedKey = "";

        public static string PrivateKey =>
            System.Text.Encoding.UTF8.GetString(System.Convert.FromBase64String(EncodedKey));
    }
}
